/** 🧱️ Independent Source owner law for Block3d independent semantic SQLite demand. */
import {expect,test} from 'bun:test';
import {Database} from 'bun:sqlite';
import Ajv from 'ajv';
import laws from '../../🧫️fixtures/🪶️sqlite/🔣️.json';
import * as owner from '../../🟦️.ts';
import {exportSqliteDatabase,importSqliteDatabase} from '../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts';
function specimen(raw:string){const word={bits:BigInt('0x'+raw)},text=laws.nativeCase.literal,unresolved=Reflect.get(laws.nativeCase,'unresolvedVortexKind');const kind={id:'',name:text,label:'',variant:'',description:text,icon:'',unit:''},attributes=[{key:'',value:text,definition:''}],authors=[{id:'',name:text,email:''}],compatibility=[{id:'',source:'',target:text,bidirectional:true}],meta={description:text};return{schema:'',objectKind:kind,representations:[{id:'',name:text,meshUrl:'',tags:['',text],lod:'',description:text,attributes:[{key:'',value:text,definition:''}]}],catalog:{childId:'local\0!@/😀',target:{artifactId:'target\0!@/😀',dialect:{artifactKind:'s.stdio.semio',standard:'v1',subset:'kit'}}},vortexKindExtra:[{id:'',name:text,label:'',color:'',defaultCableKind:text}],vortices:[{id:'',vortexKind:unresolved,position:[word,word,word],direction:[word,word,word],radius:word,label:''}],compatibility,attributes,authors,camera3d:{position:[word,word,word],target:[word,word,word],zoom:word},meta};}
function codecs(){const project=Reflect.get(owner,'block3dSnapshotToSqliteDatabase'),restore=Reflect.get(owner,'block3dSnapshotFromSqliteDatabase');expect(typeof project).toBe('function');expect(typeof restore).toBe('function');return{project,restore};}
expect(new Ajv({strict:true}).validate(facetSchema,facets)).toBe(true);
for(const raw of laws.binary64Bits)test('Block3d complete owned IEEE word '+raw,async()=>{expect(new Ajv({strict:true}).compile(facets.wordSchema)({bits:raw})).toBe(true);const bytes=Buffer.from(raw,'hex');expect(new DataView(bytes.buffer,bytes.byteOffset,8).getBigUint64(0)).toBe(BigInt('0x'+raw));const value=specimen(raw);expect(owner.parseBlock3dSnapshot(value)).toEqual(value);const{project,restore}=codecs(),database=await project(value),db=Database.deserialize(await exportSqliteDatabase(database),{safeIntegers:true});try{expect(db.query('PRAGMA integrity_check').get()).toEqual({integrity_check:'ok'});expect(db.query('PRAGMA foreign_key_check').all()).toEqual([]);for(const[name,count]of Object.entries(facets.tableRowCounts))expect(db.query('SELECT COUNT(*) AS count FROM '+name).get()).toEqual({count:BigInt(count)});expect(await restore(await importSqliteDatabase(db.serialize()))).toEqual(value);db.query('UPDATE block3_meta SET description=?').run('independent\0😀');expect(await restore(await importSqliteDatabase(db.serialize()))).toEqual({...value,meta:{description:'independent\0😀'}});}finally{db.close();}});
for(const sql of facets.malformedSql)test('Block3d exact independent malformed SQL '+sql,async()=>{const{project,restore}=codecs(),db=Database.deserialize(await exportSqliteDatabase(await project(specimen(laws.binary64Bits[5]!))));try{db.exec('PRAGMA foreign_keys=OFF');db.exec('PRAGMA ignore_check_constraints=ON');db.exec(sql);await expect(restore(await importSqliteDatabase(db.serialize()))).rejects.toThrow();}finally{db.close();}});

import facets from '../../🧫️fixtures/🪶️sqlite/🧭️source/🔣️.json';
import facetSchema from '../../🧫️fixtures/🪶️sqlite/🧭️source/🧬️schema/🔣️.json';
function at(value:any,path:readonly(string|number)[]):any{return path.reduce((row,key)=>row[key],value);}
function set(value:any,path:readonly(string|number)[],next:unknown):void{at(value,path.slice(0,-1))[path[path.length-1]!]=next;}
test('closed independently authored Source facets',()=>{expect(new Ajv({strict:true}).validate(facetSchema,facets)).toBe(true)});
for(const path of facets.optionalPaths)for(const state of ['absent','present'] as const)test('optional owned state '+JSON.stringify(path)+':'+state,async()=>{const value=specimen(laws.binary64Bits[5]!),original=at(value,path);set(value,path,state==='absent'?null:original);const{project,restore}=codecs();expect(await restore(await importSqliteDatabase(await exportSqliteDatabase(await project(value))))).toEqual(value)});
for(const path of facets.extraPaths)test('strict extra owned field refusal '+JSON.stringify(path),async()=>{const value=specimen(laws.binary64Bits[5]!);at(value,path).foreign=true;const{project}=codecs();await expect(project(value)).rejects.toThrow()});
for(const edit of facets.nestedEdits)test('independent complete nested SQL edit '+edit.sql,async()=>{const value=specimen(laws.binary64Bits[5]!),expected=structuredClone(value);set(expected,edit.path,edit.value);const{project,restore}=codecs(),db=Database.deserialize(await exportSqliteDatabase(await project(value)));try{db.exec(edit.sql);expect(db.query('PRAGMA integrity_check').get()).toEqual({integrity_check:'ok'});expect(db.query('PRAGMA foreign_key_check').all()).toEqual([]);expect(await restore(await importSqliteDatabase(db.serialize()))).toEqual(expected)}finally{db.close()}});
import {sqliteOperation} from '../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts';
test('same caller cumulative allocation and interior cancellation preserve full owner',async()=>{const value=specimen(laws.binary64Bits[5]!);value.authors=Array.from({length:facets.control.repeat},()=>({...value.authors[0]!,name:facets.control.literal}));const{project,restore}=codecs(),probe=sqliteOperation();const database=await project(value,probe);expect(probe.ownedBytes).toBeGreaterThan(0);const exact=sqliteOperation({maxAllocationBytes:probe.ownedBytes});expect(await project(value,exact)).toEqual(database);await expect(project(value,exact)).rejects.toMatchObject({kind:'ownershipLimit'});await expect(project(value,{maxAllocationBytes:probe.ownedBytes-1})).rejects.toMatchObject({kind:'ownershipLimit'});const restoreProbe=sqliteOperation();expect(await restore(database,restoreProbe)).toEqual(value);expect(restoreProbe.ownedBytes).toBeGreaterThan(0);const restoreExact=sqliteOperation({maxAllocationBytes:restoreProbe.ownedBytes});expect(await restore(database,restoreExact)).toEqual(value);await expect(restore(database,restoreExact)).rejects.toMatchObject({kind:'ownershipLimit'});await expect(restore(database,{maxAllocationBytes:restoreProbe.ownedBytes-1})).rejects.toMatchObject({kind:'ownershipLimit'});for(const direction of ['project','restore']){const controller=new AbortController();let interior=false;const options={signal:controller.signal,onProgress:(p:any)=>{if(p.completed>=facets.control.minimumInterior&&p.completed<p.total){interior=true;controller.abort()}}};await expect(direction==='project'?project(value,options):restore(database,options)).rejects.toMatchObject({kind:facets.control.requiredKind});expect(interior).toBe(true)}});

import transport from '../../🧫️fixtures/🪶️sqlite/🔢️transport/🔣️.json';
import transportSchema from '../../🧫️fixtures/🪶️sqlite/🔢️transport/🧬️schema/🔣️.json';
test('closed genuine JSON transport preserves every declared binary64 word and rejects malformed carriers',()=>{
 expect(new Ajv({strict:true}).validate(transportSchema,transport)).toBe(true);
 const write=Reflect.get(owner,'block3dSnapshotToJsonText'),read=Reflect.get(owner,'block3dSnapshotFromJsonText');
 expect(typeof write).toBe('function');expect(typeof read).toBe('function');
 const validate=new Ajv({strict:true}).compile(transport.wordSchema);
 for(const word of transport.words){const value=specimen(word),text=write(value),parsed=JSON.parse(text);for(const path of transport.roles){expect(validate(at(parsed,path))).toBe(true);expect(at(parsed,path)).toEqual({bits:word});const bytes=Buffer.from(at(parsed,path).bits,'hex');expect(new DataView(bytes.buffer,bytes.byteOffset,8).getBigUint64(0)).toBe(BigInt('0x'+word));}expect(read(text)).toEqual(value);for(const invalid of transport.invalidWords){const bad=JSON.parse(text);set(bad,transport.roles[0]!,invalid);expect(()=>read(JSON.stringify(bad))).toThrow();}}
});
test('typed Semio Kit catalog dialect is admitted across literal child identities and SQL directions',async()=>{
 const{project,restore}=codecs();for(const dialect of transport.childDialects.accepted){const value=specimen(transport.words[0]!);value.catalog.target.dialect=dialect;expect(owner.parseBlock3dSnapshot(value)).toEqual(value);expect(await restore(await project(value))).toEqual(value);}
 for(const dialect of transport.childDialects.refused){const value=specimen(transport.words[0]!);value.catalog.target.dialect=dialect;expect(()=>owner.parseBlock3dSnapshot(value)).toThrow();await expect(project(value)).rejects.toThrow();const good=specimen(transport.words[0]!),db=Database.deserialize(await exportSqliteDatabase(await project(good)));try{db.query('UPDATE block3_catalog_child SET artifact_kind=?,standard=?,subset=?').run(dialect.artifactKind,dialect.standard,dialect.subset);await expect(restore(await importSqliteDatabase(db.serialize()))).rejects.toThrow();}finally{db.close();}}
});

